script/Deploy.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Script, console2} from "forge-std/Script.sol";
import {Vm, VmSafe} from "forge-std/Vm.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {CurvePad} from "../src/CurvePad.sol";
import {PositionLocker} from "../src/PositionLocker.sol";
import {IPositionManager} from "../src/interfaces/IUniswapV4.sol";
import {Addresses} from "./Addresses.sol";
import {CurveConstants} from "./CurveConstants.sol";
import {HookMiner} from "./HookMiner.sol";
import {LivePrices} from "./LivePrices.sol";

interface ISafeView {
    function getThreshold() external view returns (uint256);
    function getOwners() external view returns (address[] memory);
}

/// @notice Shared X Layer wiring for the deploy script and fork tests.
library CircDeploy {
    Vm private constant vm = Vm(address(uint160(uint256(keccak256("hevm cheat code")))));

    /// @dev Fixed constants from CurveConstants (tests). See deployWith.
    function deploy(address deployer, address protocol, address sink)
        internal
        returns (CurvePad pad, PositionLocker locker)
    {
        return deployWith(deployer, protocol, sink, CurveConstants.wokb(), CurveConstants.bem(), Addresses.BEM);
    }

    /// @dev Deploys PositionLocker then CurvePad from `deployer`, whose next two nonces must be these two creates.
    /// `bemToken` is the BEM-slot quote asset (Addresses.BEM in production; tests may substitute a mock).
    function deployWith(
        address deployer,
        address protocol,
        address sink,
        CurvePad.QuoteConfig memory wokbConfig,
        CurvePad.QuoteConfig memory bemConfig,
        address bemToken
    ) internal returns (CurvePad pad, PositionLocker locker) {
        address predictedPad = vm.computeCreateAddress(deployer, vm.getNonce(deployer) + 1);
        (bytes32 hookSalt,) = HookMiner.mine(predictedPad, Addresses.POOL_MANAGER, Addresses.POSITION_MANAGER);
        locker = new PositionLocker(IPositionManager(Addresses.POSITION_MANAGER), predictedPad, protocol, sink);
        pad = new CurvePad(
            CurvePad.Params({
                wokb: Addresses.WOKB,
                bem: bemToken,
                wokbConfig: wokbConfig,
                bemConfig: bemConfig,
                circuitFactory: Addresses.CIRCUIT_FACTORY,
                registry: Addresses.ERC6551_REGISTRY,
                containerImpl: Addresses.CONTAINER_IMPL,
                poolManager: Addresses.POOL_MANAGER,
                positionManager: Addresses.POSITION_MANAGER,
                permit2: Addresses.PERMIT2,
                locker: address(locker),
                protocol: protocol,
                sink: sink,
                hookSalt: hookSalt
            })
        );
        require(address(pad) == predictedPad, "pad address mismatch");
    }
}

/// @notice Checks and logging shared by the production and TEST deploy scripts.
abstract contract DeployGuards is Script {
    /// @dev Foundry's default script sender.
    address internal constant FOUNDRY_DEFAULT_SENDER = 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38;
    string internal constant ANVIL_MNEMONIC = "test test test test test test test test test test test junk";

    error DefaultKeyOnMainnet(address broadcaster);

    function _broadcasting() internal view returns (bool) {
        return vm.isContext(VmSafe.ForgeContext.ScriptBroadcast) || vm.isContext(VmSafe.ForgeContext.ScriptResume);
    }

    function _logDeployment(CurvePad pad, PositionLocker locker) internal view {
        console2.log("PositionLocker", address(locker));
        console2.log("CurvePad      ", address(pad));
        console2.log("CircHook      ", address(pad.hook()));
        console2.log("Graduator     ", address(pad.graduator()));
        console2.log("TokenDeployer ", address(pad.tokenDeployer()));
        console2.log("protocol      ", pad.protocol());
        console2.log("sink          ", pad.sink());
    }

    /// @dev Refuse a mainnet broadcast from any publicly known key: the Foundry default sender or the first 20 accounts of
    /// anvil's default mnemonic.
    function _requireNotDefaultKey(address broadcaster) internal pure {
        if (broadcaster == FOUNDRY_DEFAULT_SENDER) revert DefaultKeyOnMainnet(broadcaster);
        for (uint32 i; i < 20; ++i) {
            if (broadcaster == vm.addr(vm.deriveKey(ANVIL_MNEMONIC, i))) revert DefaultKeyOnMainnet(broadcaster);
        }
    }
}

/// @notice Deploys PositionLocker, then CurvePad (which creates TokenDeployer, CircHook and Graduator).
///
/// Curve constants are regenerated from live on-chain prices at run time (script/LivePrices.sol) and printed:
///   1. Dry run (no --broadcast): prints LIVE_WOKB_VQUOTE0 / LIVE_BEM_VQUOTE0 and what they mean in USD.
///   2. The owner approves those numbers.
///   3. Broadcast run: set APPROVED_WOKB_VQUOTE0 / APPROVED_BEM_VQUOTE0 to the approved values. The script deploys with
///      exactly those, and refuses if live prices have since moved them by more than MAX_DRIFT_BPS.
/// Env: PRIVATE_KEY, CIRC_PROTOCOL, CIRC_SINK (+ APPROVED_* when broadcasting).
/// Never add --broadcast against mainnet without the owner's explicit go-ahead.
contract Deploy is DeployGuards {
    uint256 internal constant MAX_DRIFT_BPS = 200; // 2%

    error ApprovalRequired();
    error RecipientNotAContract(string name, address account);
    error PricesMovedSinceApproval(string quote, uint256 approved, uint256 live);

    function run() external returns (CurvePad pad, PositionLocker locker) {
        require(block.chainid == 196 || block.chainid == 31337, "X Layer mainnet or local fork only");
        uint256 pk = vm.envUint("PRIVATE_KEY");
        address deployer = vm.addr(pk);
        bool broadcasting = _broadcasting();
        if (broadcasting && block.chainid == 196) _requireNotDefaultKey(deployer);
        address protocol = vm.envAddress("CIRC_PROTOCOL");
        address sink = vm.envAddress("CIRC_SINK");

        (uint128 wokbVQ0, uint128 bemVQ0) = _constants(broadcasting);
        _requireSafe("CIRC_PROTOCOL", protocol);
        _requireSafe("CIRC_SINK", sink);

        vm.startBroadcast(pk);
        (pad, locker) = CircDeploy.deployWith(
            deployer, protocol, sink, LivePrices.config(wokbVQ0), LivePrices.config(bemVQ0), Addresses.BEM
        );
        vm.stopBroadcast();
        _logDeployment(pad, locker);
    }

    /// @dev Live constants on a dry run; owner-approved constants (checked against live) on a broadcast.
    function _constants(bool broadcasting) internal view returns (uint128 wokbVQ0, uint128 bemVQ0) {
        (uint256 okbUsd, uint256 bemUsd) = LivePrices.read();
        uint128 liveW = LivePrices.vQuote0(okbUsd, 18);
        uint128 liveB = LivePrices.vQuote0(bemUsd, 8);

        console2.log("=== Curve constants from live prices (block %s) ===", block.number);
        console2.log("OKB_USD_E18", okbUsd);
        console2.log("BEM_USD_E18", bemUsd);
        console2.log("LIVE_WOKB_VQUOTE0", uint256(liveW));
        console2.log("LIVE_BEM_VQUOTE0", uint256(liveB));
        console2.log("WOKB raise R (wei)", LivePrices.raise(liveW));
        console2.log("BEM raise R (8dp)", LivePrices.raise(liveB));
        console2.log("raise in USD (both)", LivePrices.raise(liveW) * okbUsd / 1e36);
        console2.log("vToken0 / curveSupply / lpTokens (fixed):");
        console2.log(uint256(CurveConstants.V_TOKEN0), uint256(CurveConstants.CURVE_SUPPLY), uint256(CurveConstants.LP_TOKENS));

        if (!broadcasting) return (liveW, liveB);

        uint256 approvedW = vm.envOr("APPROVED_WOKB_VQUOTE0", uint256(0));
        uint256 approvedB = vm.envOr("APPROVED_BEM_VQUOTE0", uint256(0));
        if (approvedW == 0 || approvedB == 0) revert ApprovalRequired();
        _checkDrift("WOKB", approvedW, liveW);
        _checkDrift("BEM", approvedB, liveB);
        console2.log("Using APPROVED constants:", approvedW, approvedB);
        return (uint128(approvedW), uint128(approvedB));
    }

    /// @dev Production fee recipients must be contracts (the owner's Safes), never EOAs. Prints Safe threshold/owners when
    /// the account answers the Safe interface.
    function _requireSafe(string memory name, address account) internal view {
        console2.log(name, account);
        console2.log("  code size", account.code.length);
        if (account.code.length == 0) revert RecipientNotAContract(name, account);
        try ISafeView(account).getThreshold() returns (uint256 t) {
            address[] memory owners = ISafeView(account).getOwners();
            console2.log("  Safe threshold %s of %s owners", t, owners.length);
        } catch {
            console2.log("  (does not answer the Safe interface)");
        }
    }

    function _checkDrift(string memory quote, uint256 approved, uint256 live) internal pure {
        uint256 diff = approved > live ? approved - live : live - approved;
        if (diff * 10_000 > live * MAX_DRIFT_BPS) revert PricesMovedSinceApproval(quote, approved, live);
    }

}

/// @notice CIRC-TEST instance: the same contracts and constructor checks as production, with a tiny WOKB curve so a
/// launch completes after ~0.1 OKB of buys (TEST_RAISE_WEI, default 0.099 WOKB raise + 1% fee). For the end-to-end
/// test only (script/e2e); never point a frontend at it. The BEM slot gets a 1-BEM raise and is not exercised.
/// Env: PRIVATE_KEY, CIRC_PROTOCOL, CIRC_SINK, optional TEST_RAISE_WEI (capped at MAX_TEST_RAISE).
contract DeployTest is DeployGuards {
    string public constant LABEL = "CIRC-TEST";
    uint256 internal constant DEFAULT_TEST_RAISE = 0.099 ether;
    uint256 internal constant MAX_TEST_RAISE = 0.2 ether;
    uint256 internal constant TEST_BEM_RAISE = 1e8; // 1 BEM (8 dp)

    error TestRaiseTooLarge(uint256 raise);

    function run() external returns (CurvePad pad, PositionLocker locker) {
        require(block.chainid == 196 || block.chainid == 31337, "X Layer mainnet or local fork only");
        uint256 pk = vm.envUint("PRIVATE_KEY");
        address deployer = vm.addr(pk);
        if (_broadcasting() && block.chainid == 196) _requireNotDefaultKey(deployer);
        uint256 raise = vm.envOr("TEST_RAISE_WEI", DEFAULT_TEST_RAISE);
        if (raise == 0 || raise > MAX_TEST_RAISE) revert TestRaiseTooLarge(raise);

        (uint128 wokbVQ0, uint128 bemVQ0) = testVQuote0(raise);
        console2.log("=== %s deploy (TEST profile) ===", LABEL);
        console2.log("TEST_WOKB_VQUOTE0", uint256(wokbVQ0));
        console2.log("TEST_WOKB_RAISE_WEI", LivePrices.raise(wokbVQ0));
        console2.log("TEST_BEM_VQUOTE0", uint256(bemVQ0));

        vm.startBroadcast(pk);
        (pad, locker) = CircDeploy.deployWith(
            deployer,
            vm.envAddress("CIRC_PROTOCOL"),
            vm.envAddress("CIRC_SINK"),
            LivePrices.config(wokbVQ0),
            LivePrices.config(bemVQ0),
            Addresses.BEM
        );
        vm.stopBroadcast();
        console2.log("LABEL", LABEL);
        _logDeployment(pad, locker);
    }

    /// @dev vQuote0 whose raise R = vQ0 * curveSupply / tEnd equals `raise` (rounded down).
    function testVQuote0(uint256 raise) public pure returns (uint128 wokbVQ0, uint128 bemVQ0) {
        uint256 tEnd = uint256(CurveConstants.V_TOKEN0) - CurveConstants.CURVE_SUPPLY;
        wokbVQ0 = uint128(Math.mulDiv(raise, tEnd, CurveConstants.CURVE_SUPPLY));
        bemVQ0 = uint128(Math.mulDiv(TEST_BEM_RAISE, tEnd, CurveConstants.CURVE_SUPPLY));
    }
}

script/Gate2Sample.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Script, console2} from "forge-std/Script.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {CurvePad} from "../src/CurvePad.sol";
import {PositionLocker} from "../src/PositionLocker.sol";
import {PoolKey, IPositionManager, IAllowanceTransfer} from "../src/interfaces/IUniswapV4.sol";
import {ICircuitNFT} from "../src/interfaces/ITapeOut.sol";
import {Addresses} from "./Addresses.sol";

interface IStateView2 {
    function getSlot0(bytes32 poolId) external view returns (uint160, int24, uint24, uint24);
    function getLiquidity(bytes32 poolId) external view returns (uint128);
}

interface IUniversalRouter2 {
    function execute(bytes calldata commands, bytes[] calldata inputs, uint256 deadline) external payable;
}

/// @dev v4-periphery IV4Router.ExactInputSingleParams (commit pinned by Universal Router 2.1.x).
struct ExactInSingle {
    PoolKey poolKey;
    bool zeroForOne;
    uint128 amountIn;
    uint128 amountOutMinimum;
    uint256 minHopPriceX36;
    bytes hookData;
}

/// @notice GATE 2 sample run on an anvil fork (never mainnet): launch -> fill -> graduate -> trade -> collect.
/// Env: CIRC_PAD (deployed CurvePad), BUYER_KEY (funded fork key). The launch is sent as the Nandout holder, which anvil
/// impersonates (--auto-impersonate + --unlocked). Between `launch()` and `finish()`, mine GUARD_BLOCKS blocks.
contract Gate2Sample is Script {
    function launch() external returns (address token) {
        require(block.chainid == 196 || block.chainid == 31337, "fork only");
        CurvePad pad = CurvePad(payable(vm.envAddress("CIRC_PAD")));
        address holder = Addresses.NANDOUT_HOLDER;
        uint256 id = vm.envOr("CIRCUIT_ID", uint256(1));
        require(ICircuitNFT(Addresses.NANDOUT).ownerOf(id) == holder, "holder no longer owns the circuit");
        vm.startBroadcast(holder);
        token = pad.createLaunch(Addresses.NANDOUT, id, "Circ Gate Two", "CGT", Addresses.WOKB, 0, 0);
        vm.stopBroadcast();
        console2.log("TOKEN", token);
        (,,,,, address container,,,,) = pad.curves(token);
        console2.log("container", container);
    }

    function finish() external {
        require(block.chainid == 196 || block.chainid == 31337, "fork only");
        CurvePad pad = CurvePad(payable(vm.envAddress("CIRC_PAD")));
        address token = vm.envAddress("CIRC_TOKEN");
        uint256 buyerKey = vm.envUint("BUYER_KEY");
        address buyer = vm.addr(buyerKey);
        PositionLocker locker = PositionLocker(pad.locker());

        // Fill the curve with native OKB (excess refunded) -> Complete.
        (, uint256 need) = pad.previewBuy(token, type(uint128).max);
        console2.log("quote to complete (WOKB wei)", need);
        vm.startBroadcast(buyerKey);
        pad.buyWithOKB{value: need}(token, 0, block.timestamp + 1 hours);
        vm.stopBroadcast();
        (,,,,,,,,, CurvePad.Status st) = pad.curves(token);
        require(st == CurvePad.Status.Complete, "not Complete");
        console2.log("curve Complete");

        // Permissionless graduation by a keeper (here: the buyer key).
        vm.startBroadcast(buyerKey);
        pad.graduate(token);
        vm.stopBroadcast();

        PoolKey memory key = pad.graduator().poolKey(token, Addresses.WOKB);
        bytes32 poolId = keccak256(abi.encode(key));
        uint256 positionId = IPositionManager(Addresses.POSITION_MANAGER).nextTokenId() - 1;
        require(IPositionManager(Addresses.POSITION_MANAGER).ownerOf(positionId) == address(locker), "not locked");
        (, uint128 vQuote, uint128 vToken,,,,,,,) = pad.curves(token);
        (uint160 sqrtP,,,) = IStateView2(Addresses.STATE_VIEW).getSlot0(poolId);
        uint256 expectX192 =
            token < Addresses.WOKB ? Math.mulDiv(vQuote, 1 << 192, vToken) : Math.mulDiv(vToken, 1 << 192, vQuote);
        uint256 gotX192 = Math.mulDiv(sqrtP, sqrtP, 1);
        uint256 diff = gotX192 > expectX192 ? gotX192 - expectX192 : expectX192 - gotX192;
        require(diff * 1000 <= expectX192, "pool price off P_end by > 0.1%");
        console2.log("POOL_ID");
        console2.logBytes32(poolId);
        console2.log("POSITION_ID", positionId);
        console2.log("locked liquidity", uint256(IPositionManager(Addresses.POSITION_MANAGER).getPositionLiquidity(positionId)));
        console2.log("hook open", pad.hook().isOpen(poolId));

        // Sell 1M tokens through Universal Router 2.1.2, then collect LP fees into the locker.
        uint256 amountIn = 1_000_000 ether;
        bool zeroForOne = token == key.currency0;
        bytes[] memory params = new bytes[](3);
        params[0] = abi.encode(ExactInSingle(key, zeroForOne, uint128(amountIn), 0, 0, bytes("")));
        params[1] = abi.encode(token, amountIn);
        params[2] = abi.encode(Addresses.WOKB, uint256(0));
        bytes[] memory inputs = new bytes[](1);
        inputs[0] = abi.encode(abi.encodePacked(uint8(0x06), uint8(0x0c), uint8(0x0f)), params);
        uint256 before = IERC20(Addresses.WOKB).balanceOf(buyer);
        vm.startBroadcast(buyerKey);
        IERC20(token).approve(Addresses.PERMIT2, type(uint256).max);
        IAllowanceTransfer(Addresses.PERMIT2).approve(
            token, Addresses.UNIVERSAL_ROUTER, uint160(amountIn), uint48(block.timestamp + 1 hours)
        );
        IUniversalRouter2(Addresses.UNIVERSAL_ROUTER).execute(
            abi.encodePacked(uint8(0x10)), inputs, block.timestamp + 1 hours
        );
        locker.collect(positionId);
        vm.stopBroadcast();
        console2.log("WOKB received from UR sell", IERC20(Addresses.WOKB).balanceOf(buyer) - before);
        console2.log("locker token fees accrued", locker.totalAccrued(token));
        console2.log("GATE2 SAMPLE RUN OK");
    }
}

script/HookMiner.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {CircHook} from "../src/CircHook.sol";

/// @notice Finds the CREATE2 salt CurvePad uses for CircHook. Run off-chain (script / test), never on-chain.
library HookMiner {
    uint160 internal constant FLAG_MASK = (1 << 14) - 1;
    uint160 internal constant FLAGS = (1 << 13) | (1 << 11); // BEFORE_INITIALIZE | BEFORE_ADD_LIQUIDITY
    uint256 internal constant MAX_LOOP = 400_000;

    error SaltNotFound();

    /// @param pad the CurvePad address that will deploy the hook (CREATE2 deployer)
    /// @return salt the CREATE2 salt
    /// @return hook the resulting hook address
    function mine(address pad, address poolManager, address positionManager)
        internal
        pure
        returns (bytes32 salt, address hook)
    {
        bytes32 initHash = keccak256(
            abi.encodePacked(type(CircHook).creationCode, abi.encode(graduatorOf(pad), poolManager, positionManager))
        );
        for (uint256 i; i < MAX_LOOP; ++i) {
            salt = bytes32(i);
            hook = address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), pad, salt, initHash)))));
            uint160 h = uint160(hook);
            if (h & FLAG_MASK == FLAGS && h >> 152 != 0x91) return (salt, hook);
        }
        revert SaltNotFound();
    }

    /// @dev CurvePad creates Graduator as its third creation (nonce 3).
    function graduatorOf(address pad) internal pure returns (address) {
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xd6), bytes1(0x94), pad, uint8(3))))));
    }
}

script/LivePrices.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {CurvePad} from "../src/CurvePad.sol";
import {Addresses} from "./Addresses.sol";
import {CurveConstants} from "./CurveConstants.sol";

interface IV3PoolPrice {
    function slot0() external view returns (uint160, int24, uint16, uint16, uint16, uint8, bool);
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IDecimals {
    function decimals() external view returns (uint8);
}

/// @notice Deploy-time curve constants from live on-chain prices. Token-side constants (vToken0, curveSupply, lpTokens)
/// depend only on the launch/graduation market-cap ratio and stay as in CurveConstants; vQuote0 is re-solved per quote
/// asset so graduation lands at GRAD_MC_USD at the prices read here. Spot prices: only for a human-approved deploy.
library LivePrices {
    uint256 internal constant GRAD_MC_USD = 69_000;
    uint256 internal constant LAUNCH_MC_USD = 4_000;

    /// @return okbUsdE18 USD per OKB, 1e18 fixed point (USD₮0/WOKB pool)
    /// @return bemUsdE18 USD per BEM, 1e18 fixed point (BEM/WOKB pool x OKB/USD)
    function read() internal view returns (uint256 okbUsdE18, uint256 bemUsdE18) {
        okbUsdE18 = priceE18(Addresses.WOKB_USDT0_POOL, Addresses.WOKB);
        uint256 bemInOkbE18 = priceE18(Addresses.BEM_WOKB_POOL, Addresses.BEM);
        bemUsdE18 = Math.mulDiv(bemInOkbE18, okbUsdE18, 1e18);
    }

    /// @dev Human price of one `base` in the pool's other token, 1e18 fixed point, from slot0.
    function priceE18(address pool, address base) internal view returns (uint256) {
        (uint160 sqrtP,,,,,,) = IV3PoolPrice(pool).slot0();
        address t0 = IV3PoolPrice(pool).token0();
        address t1 = IV3PoolPrice(pool).token1();
        require(base == t0 || base == t1, "base not in pool");
        uint256 d0 = 10 ** IDecimals(t0).decimals();
        uint256 d1 = 10 ** IDecimals(t1).decimals();
        uint256 ratioX128 = Math.mulDiv(sqrtP, sqrtP, 1 << 64); // raw token1 per raw token0, Q128
        // base = token0: token1 per token0 = ratio * d0 / d1;  base = token1: token0 per token1 = d1 / (ratio * d0)
        return base == t0
            ? Math.mulDiv(ratioX128, d0 * 1e18, (1 << 128) * d1)
            : Math.mulDiv((1 << 128) * d1, 1e18, ratioX128 * d0);
    }

    /// @notice vQuote0 for a quote asset priced at `usdE18` with `dec` decimals (graduation MC = GRAD_MC_USD).
    function vQuote0(uint256 usdE18, uint8 dec) internal pure returns (uint128) {
        uint256 vT0 = CurveConstants.V_TOKEN0;
        uint256 tEnd = vT0 - CurveConstants.CURVE_SUPPLY;
        // vQuote0 = P_end * T_end^2 / vT0, P_end = GRAD_MC * 10^dec / (1e9 tokens * price)
        return uint128(Math.mulDiv(GRAD_MC_USD * 10 ** dec, Math.mulDiv(tEnd, tEnd, vT0), 1e9 * usdE18));
    }

    function config(uint128 vQ0) internal pure returns (CurvePad.QuoteConfig memory) {
        return CurvePad.QuoteConfig(vQ0, CurveConstants.V_TOKEN0, CurveConstants.CURVE_SUPPLY, CurveConstants.LP_TOKENS);
    }

    /// @notice Raise R at graduation for a given vQuote0 (quote-wei).
    function raise(uint128 vQ0) internal pure returns (uint256) {
        uint256 vT0 = CurveConstants.V_TOKEN0;
        return Math.mulDiv(vQ0, vT0, vT0 - CurveConstants.CURVE_SUPPLY) - vQ0;
    }
}

